import bpy, os
out = r'C:\mcp-blender\blender_bridge\previews\upper_refinement_test.png'
os.makedirs(os.path.dirname(out), exist_ok=True)
coll = bpy.data.collections.get('07 REFINO ENTRADA SUPERIOR | ChatGPT')
if not coll: raise RuntimeError('refinement collection missing')
bpy.ops.object.select_all(action='DESELECT')
for o in coll.objects:
    try:
        o.hide_set(False); o.select_set(True)
    except Exception: pass
area_found=region_found=window_found=None
for window in bpy.context.window_manager.windows:
    for area in window.screen.areas:
        if area.type=='VIEW_3D':
            region=next((r for r in area.regions if r.type=='WINDOW'),None)
            if region:
                window_found,area_found,region_found=window,area,region; break
    if area_found: break
if not area_found: raise RuntimeError('Nenhuma VIEW_3D encontrada')
with bpy.context.temp_override(window=window_found,screen=window_found.screen,area=area_found,region=region_found):
    bpy.ops.view3d.view_selected(use_all_regions=False)
scene=bpy.context.scene
old=(scene.render.filepath,scene.render.resolution_x,scene.render.resolution_y,scene.render.resolution_percentage,scene.render.image_settings.file_format)
try:
    scene.render.filepath=out; scene.render.resolution_x=720; scene.render.resolution_y=540; scene.render.resolution_percentage=100; scene.render.image_settings.file_format='PNG'
    with bpy.context.temp_override(window=window_found,screen=window_found.screen,area=area_found,region=region_found):
        bpy.ops.render.opengl(write_still=True,view_context=True)
finally:
    scene.render.filepath,scene.render.resolution_x,scene.render.resolution_y,scene.render.resolution_percentage,scene.render.image_settings.file_format=old
print(f'UPPER_REFINEMENT_SNAPSHOT={out}; SIZE={os.path.getsize(out)}')
